import{_ as p,a0 as d,w as s,s as l,I as o,x as t,a1 as a,A as n,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"5 個提高效率的 GNOME 快捷鍵 | LCTT x X-CMD","titleTemplate":false,"description":"5 個提高效率的 GNOME 快捷鍵 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 個提高效率的 GNOME 快捷鍵 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 個提高效率的 GNOME 快捷鍵 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190527 5 GNOME keyboard shortcuts to be more productive","title":"5 個提高效率的 GNOME 快捷鍵","tag":"201906","desc":""},"relativePath":"201906/20190527 5 GNOME keyboard shortcuts to be more productive.md","filePath":"[post].md"}'),u={name:"201906/20190527 5 GNOME keyboard shortcuts to be more productive.md"};function m(f,e,g,h,E,b){const r=d("Link");return s(),l("div",null,[e[25]||(e[25]=o("h1",{id:"_5-個提高效率的-gnome-快捷鍵",tabindex:"-1"},[t("5 個提高效率的 GNOME 快捷鍵 "),o("a",{class:"header-anchor",href:"#_5-個提高效率的-gnome-快捷鍵","aria-label":"Permalink to “5 個提高效率的 GNOME 快捷鍵”"},"​")],-1)),e[26]||(e[26]=o("p",null,[o("img",{src:"https://fedoramagazine.org/wp-content/uploads/2019/05/5-gnome-keycombos-816x345.jpg",alt:""})],-1)),o("p",null,[e[1]||(e[1]=t("對於某些人來説，使用 GNOME Shell 作為傳統的桌面管理器可能會感覺沮喪，因為它通常需要更多的鼠標操作。事實上，GNOME Shell 也是一個專為鍵盤操作而設計的",-1)),a(r,{href:"https://fedoramagazine.org/gnome-3-32-released-coming-to-fedora-30/"},{default:n(()=>[...e[0]||(e[0]=[t("桌面管理器",-1)])]),_:1}),e[2]||(e[2]=t("。通過這五種使用鍵盤而不是鼠標的方法，瞭解如何使用 GNOME Shell 提高效率。",-1))]),e[27]||(e[27]=i('<h3 id="gnome-活動概述" tabindex="-1">GNOME 活動概述 <a class="header-anchor" href="#gnome-活動概述" aria-label="Permalink to “GNOME 活動概述”">​</a></h3><p>可以使用鍵盤上的 <code>Super</code> 鍵輕鬆打開活動概述。（<code>Super</code> 鍵通常有一個標識——比如 Windows 徽標……）這在啓動應用程序時非常有用。例如，使用以下鍵序列 <code>Super + f i r + Enter</code> 可以輕鬆啓動 Firefox Web 瀏覽器</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-10-50.gif" alt=""></p><h3 id="消息托盤" tabindex="-1">消息托盤 <a class="header-anchor" href="#消息托盤" aria-label="Permalink to “消息托盤”">​</a></h3><p>在 GNOME 中，消息托盤中提供了通知。這也是日曆和世界時鐘出現的地方。要使用鍵盤打開信息托盤，請使用 <code>Super + m</code> 快捷鍵。要關閉消息托盤，只需再次使用相同的快捷方式。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-11-01.gif" alt=""></p><h3 id="在-gnome-中管理工作空間" tabindex="-1">在 GNOME 中管理工作空間 <a class="header-anchor" href="#在-gnome-中管理工作空間" aria-label="Permalink to “在 GNOME 中管理工作空間”">​</a></h3><p>GNOME Shell 使用動態工作空間，這意味着它可以根據需要創建更多工作空間。使用 GNOME 提高工作效率的一個好方法是為每個應用程序或每個專用活動使用一個工作區，然後使用鍵盤在這些工作區之間導航。</p><p>讓我們看一個實際的例子。要在當前工作區中打開終端，請按以下鍵：<code>Super + t e r + Enter</code>。然後，要打開新工作區，請按 <code>Super + PgDn</code>。 打開 Firefox（ <code>Super + f i r + Enter</code>）。 要返回終端（所在的工作空間），請使用 <code>Super + PgUp</code>。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-12-57.gif" alt=""></p><h3 id="管理應用窗口" tabindex="-1">管理應用窗口 <a class="header-anchor" href="#管理應用窗口" aria-label="Permalink to “管理應用窗口”">​</a></h3><p>使用鍵盤也可以輕鬆管理應用程序窗口的大小。最小化、最大化和將應用程序移動到屏幕的左側或右側只需幾個擊鍵即可完成。使用 <code>Super + ↑</code> 最大化、<code>Super + ↓</code> 最小化、<code>Super + ←</code> 和 <code>Super + →</code> 左右移動窗口。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-13-06.gif" alt=""></p><h3 id="同一個應用的多個窗口" tabindex="-1">同一個應用的多個窗口 <a class="header-anchor" href="#同一個應用的多個窗口" aria-label="Permalink to “同一個應用的多個窗口”">​</a></h3><p>使用活動概述啓動應用程序非常有效。但是，嘗試從已經運行的應用程序打開一個新窗口只能將焦點轉移到已經打開的窗口。要創建一個新窗口，就不是簡單地按 <code>Enter</code> 啓動應用程序，請使用 <code>Ctrl + Enter</code>。</p><p>因此，例如，使用應用程序概述啓動終端的第二個實例，<code>Super + t e r + (Ctrl + Enter)</code>。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-13-19.gif" alt=""></p><p>然後你可以使用 <code>Super</code> + ` 在同一個應用程序的窗口之間切換。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/05/Peek-2019-05-23-13-22.gif" alt=""></p>',19)),o("p",null,[e[4]||(e[4]=t("如圖所示，當用鍵盤控制時，GNOME Shell 是一個非常強大的桌面環境。學習使用這些快捷方式並訓練你的肌肉記憶以不使用鼠標將為你提供更好的用户體驗，並在使用 GNOME 時提高你的工作效率。有關其他有用的快捷方式，請查看 ",-1)),a(r,{href:"https://wiki.gnome.org/Design/OS/KeyboardShortcuts"},{default:n(()=>[...e[3]||(e[3]=[t("GNOME wiki 上的此頁面",-1)])]),_:1}),e[5]||(e[5]=t("。",-1))]),o("p",null,[o("em",null,[e[8]||(e[8]=t("圖片來自 ",-1)),a(r,{href:"https://unsplash.com/photos/MuTWth_RnEs?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:n(()=>[...e[6]||(e[6]=[t("1AmFcS",-1)])]),_:1}),e[9]||(e[9]=t("，",-1)),a(r,{href:"https://unsplash.com/search/photos/keyboard?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:n(()=>[...e[7]||(e[7]=[t("Unsplash",-1)])]),_:1})])]),e[28]||(e[28]=o("hr",null,null,-1)),o("p",null,[e[11]||(e[11]=t("via: ",-1)),a(r,{href:"https://fedoramagazine.org/5-gnome-keyboard-shortcuts-to-be-more-productive/"},{default:n(()=>[...e[10]||(e[10]=[t("https://fedoramagazine.org/5-gnome-keyboard-shortcuts-to-be-more-productive/",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=t("作者：",-1)),a(r,{href:"https://fedoramagazine.org/author/cverna/"},{default:n(()=>[...e[12]||(e[12]=[t("Clément Verna",-1)])]),_:1}),e[17]||(e[17]=t(" 選題：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[13]||(e[13]=[t("lujun9972",-1)])]),_:1}),e[18]||(e[18]=t(" 譯者：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[14]||(e[14]=[t("wxy",-1)])]),_:1}),e[19]||(e[19]=t(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[15]||(e[15]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[22]||(e[22]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[20]||(e[20]=[t("LCTT",-1)])]),_:1}),e[23]||(e[23]=t(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:n(()=>[...e[21]||(e[21]=[t("Linux中國",-1)])]),_:1}),e[24]||(e[24]=t(" 榮譽推出",-1))])])}const k=p(u,[["render",m]]);export{S as __pageData,k as default};
